def heroes_for_difficulty(difficulty: str) -> list:
    """Список героев для выбранной сложности (копии словарей). Неизвестная сложность = сложная."""
    if difficulty == "easy":
        allowed = EASY_HEROES
    elif difficulty == "normal":
        allowed = EASY_HEROES | NORMAL_HEROES
    else:
        return [dict(h) for h in HEROES]
    return [dict(h) for h in HEROES if h["en"] in allowed]


def hero_total(hero: dict) -> int:
    return hero["power"] + hero["speed"] + hero["intelligence"]


def hero_pic_line(hero: dict) -> str:
    """Строка для картинки: '@pic superman (DC)' / '@pic hulk (MARVEL)'."""
    en = hero.get("en")
    if not en:
        return ""
    universe = hero.get("universe")
    suffix = f" ({universe.upper()})" if universe else ""
    return f"@pic {en.lower()}{suffix}"


def hero_card_text(hero: dict) -> str:
    return (
        f"🦸 <b>{hero['name']}</b> ({hero['universe']})\n"
        f"💪 Сила: {hero['power']}   ⚡ Скорость: {hero['speed']}   🧠 Интеллект: {hero['intelligence']}\n"
        f"📊 Суммарный стат: {hero_total(hero)}"
    )
def hero_card_text_hidden(hero: dict) -> str:
    return (
        f"🦸 <b>{hero['name']}</b> ({hero['universe']})\n"
        f"❓ Статы скрыты — узнаешь после покупки!"
    )